<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { createAppointment, searchAppointments, updateAppointmentStatus, type Appointment, type AppointmentAction, type AppointmentStatus } from '@/api/appointments'
import { searchPatients } from '@/api/patients'
const date=ref(new Date().toISOString().slice(0,10));const status=ref<AppointmentStatus|''>('CONFIRMED');const appointments=ref<Appointment[]>([]);const error=ref('');const form=ref({patient:'',therapistId:'1',serviceId:'1',time:'09:00',note:''})
async function load(){try{appointments.value=(await searchAppointments(date.value,status.value||undefined)).items}catch(e){error.value=e instanceof Error?e.message:'โหลดนัดหมายไม่สำเร็จ'}}
async function save(){error.value='';try{const raw=form.value.patient.trim();let patientId=Number(raw);if(raw.length>6){const result=await searchPatients(raw);const match=result.items.find(p=>p.hn===raw);if(!match)throw new Error(`ไม่พบผู้ป่วย HN ${raw}`);patientId=match.id}await createAppointment({branchCode:'RP',patientId,therapistId:Number(form.value.therapistId),serviceId:Number(form.value.serviceId),startAt:`${date.value}T${form.value.time}:00+07:00`,note:form.value.note||undefined});await load()}catch(e){error.value=e instanceof Error?e.message:'สร้างนัดหมายไม่สำเร็จ'}}
async function act(item:Appointment,action:AppointmentAction){try{await updateAppointmentStatus(item.id,action);await load()}catch(e){error.value=e instanceof Error?e.message:'เปลี่ยนสถานะไม่สำเร็จ'}}onMounted(load)
</script>
<template><section class="patient-page"><header class="patient-page-header"><div><p class="eyebrow">APPOINTMENTS</p><h1>นัดหมาย</h1><p class="page-subtitle">สร้างและจัดการนัดหมาย</p></div></header><form class="form-card" @submit.prevent="save"><h2>สร้างนัดหมาย</h2><div class="form-grid"><label>วันที่<input v-model="date" type="date" required></label><label>Patient ID หรือ HN<input v-model="form.patient" required placeholder="เช่น 1 หรือ 2601080001"></label><label>Therapist ID<input v-model="form.therapistId" type="number" min="1" required></label><label>Service ID<input v-model="form.serviceId" type="number" min="1" required></label><label>เวลา<input v-model="form.time" type="time" required></label><label class="wide">หมายเหตุ<textarea v-model="form.note"></textarea></label></div><button class="primary">สร้างนัดหมาย</button><p v-if="error" class="error">{{ error }}</p></form><label>สถานะ<select v-model="status" @change="load"><option value="CONFIRMED">นัดหมายแล้ว</option><option value="ARRIVED">มาถึงคลินิก</option><option value="IN_SERVICE">กำลังรักษา</option><option value="">ทุกสถานะ</option></select></label><div v-if="!appointments.length" class="state-card">ยังไม่มีนัดหมาย</div><div v-else class="patient-results"><article v-for="item in appointments" :key="item.id" class="patient-result-card"><div><h2>{{ item.patient.fullName }}</h2><p>{{ item.service.name }} · {{ item.status }}</p></div><div class="actions"><button v-if="item.status==='CONFIRMED'||item.status==='RESCHEDULED'" class="secondary" @click="act(item,'check-in')">เช็กอิน</button><button v-if="item.status==='ARRIVED'" class="secondary" @click="act(item,'start-service')">เริ่มบริการ</button><button v-if="item.status==='IN_SERVICE'" class="secondary" @click="act(item,'complete')">เสร็จสิ้น</button></div></article></div></section></template>
